import React, { useEffect, useState } from 'react';
import { api } from '../services/api';

const fallbackTools = [
  { name: 'Google Opal', category: 'Agent Builder', use: 'Build and deploy custom AI agents for support and operations.' },
  { name: 'Claude AI', category: 'LLM Assistant', use: 'Long-form reasoning, proposal drafting, and analysis workflows.' },
  { name: 'ChatGPT', category: 'General AI', use: 'Rapid ideation, content generation, and team productivity tasks.' },
  { name: 'Zapier', category: 'Automation', use: 'Connect apps and automate repetitive business workflows.' },
  { name: 'Make', category: 'Automation', use: 'Visual multi-step automations for complex integrations.' },
  { name: 'Midjourney', category: 'Creative AI', use: 'Generate campaign visuals and brand concept assets quickly.' }
];

const Tools = () => {
  const [tools, setTools] = useState([]);

  useEffect(() => {
    const fetchTools = async () => {
      try {
        const response = await api.tools.get();
        if (Array.isArray(response.data) && response.data.length > 0) {
          setTools(response.data);
        } else {
          setTools(fallbackTools);
        }
      } catch (error) {
        console.error('Error fetching tools:', error);
        setTools(fallbackTools);
      }
    };

    fetchTools();
  }, []);

  return (
    <div className="pg" id="page-tools">
      <div className="sec">
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '4rem', alignItems: 'end', marginBottom: '2.5rem' }}>
          <div>
            <span className="lbl reveal">Our Toolkit</span>
            <h1 className="dp reveal d1" style={{ marginTop: '.5rem' }}>
              Every AI.<br />
              <span className="gr">One team.</span>
            </h1>
          </div>
          <p className="blg reveal">We've invested hundreds of hours mastering every major AI platform so you don't have to.</p>
        </div>
        <div id="toolsDisplay" style={{ borderRadius: 'var(--r)', overflow: 'hidden', background: 'var(--bg)', border: '1px solid var(--b)' }}>
          {tools.length > 0 ? (
            <div style={{ padding: '2rem' }}>
              {tools.map((tool, index) => (
                <div key={index} style={{ padding: '1rem', borderBottom: index < tools.length - 1 ? '1px solid var(--b)' : 'none' }}>
                  <div style={{ fontWeight: '600', color: 'var(--t)' }}>{tool.name}</div>
                  <div style={{ fontSize: '0.8rem', color: 'var(--s)', marginTop: '0.25rem' }}>{tool.category} • {tool.use}</div>
                </div>
              ))}
            </div>
          ) : (
            <div style={{ padding: '4rem', textAlign: 'center', color: 'var(--s)' }}>
              Loading tools...
            </div>
          )}
        </div>
        <div style={{ textAlign: 'center', marginTop: '3rem' }}>
          <a href="/contact" className="btn bg">Get a Free AI Audit →</a>
        </div>
      </div>
    </div>
  );
};

export default Tools;
